 1→//! Secret detection and masking.
 2→//!
 3→//! This module provides functionality for detecting and masking sensitive data:
 4→//!
 5→//! - [`SecretPattern`] - Defines a pattern for identifying secrets
 6→//! - [`SecretMatcher`] - Matches environment variable names against secret patterns
 7→//! - [`OutputMasker`] - Masks secret values in output streams
 8→//! - [`BUILTIN_PATTERNS`] - Built-in patterns for common secrets
 9→//!
10→//! # Example
11→//!
12→//! ```
13→//! use bivvy::secrets::{SecretMatcher, OutputMasker};
14→//!
15→//! // Check if an environment variable is a secret
16→//! let matcher = SecretMatcher::with_builtins();
17→//! assert!(matcher.is_secret("API_KEY"));
18→//! assert!(matcher.is_secret("DATABASE_URL"));
19→//! assert!(!matcher.is_secret("PATH"));
20→//!
21→//! // Mask secret values in output
22→//! let mut masker = OutputMasker::new();
23→//! masker.add_secret("super-secret-value");
24→//! let output = masker.mask("The key is super-secret-value here");
25→//! assert!(!output.contains("super-secret-value"));
26→//! ```
27→
28→pub mod mask;
29→pub mod pattern;
30→
31→pub use mask::{MaskingWriter, OutputMasker};
32→pub use pattern::{SecretMatcher, SecretPattern, BUILTIN_PATTERNS};
33→

