    #[test]
    fn scrub_removes_home_paths() {
        let input = "Error at /home/user/project/file.rs:42";
        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
        assert!(scrubbed.contains("[PATH]"));
        assert!(!scrubbed.contains("/home/user"));
    }

    // ── TelemetryConsent Display ──────────────────────────────────────

    #[test]
    fn consent_display_all_variants() {
        assert_eq!(TelemetryConsent::Send.to_string(), "send");
        assert_eq!(TelemetryConsent::NoThanks.to_string(), "no_thanks");
        assert_eq!(TelemetryConsent::Always.to_string(), "always");
        assert_eq!(TelemetryConsent::Never.to_string(), "never");
    }

    // ── scrub_for_telemetry: additional edge cases ────────────────────

    #[test]
    fn scrub_empty_input() {
        let scrubbed = scrub_for_telemetry("", &HashMap::new());
        assert_eq!(scrubbed, "");
    }

    #[test]
    fn scrub_removes_tmp_paths() {
        let input = "Wrote to /tmp/build-cache/artifact.tar.gz";
        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
        assert!(scrubbed.contains("[PATH]"));
        assert!(!scrubbed.contains("/tmp/build-cache"));
    }

    #[test]
    fn scrub_removes_windows_paths() {
        let input = r"Error at C:\Users\brenna\project\main.rs";
        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
        assert!(scrubbed.contains("[PATH]"));
        assert!(!scrubbed.contains(r"C:\Users\brenna"));
    }

    #[test]
    fn scrub_removes_gho_tokens() {
        let input = "token: gho_abcdefghijklmnopqrstuvwxyz1234567890";
        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
        assert!(scrubbed.contains("[REDACTED]"));
        assert!(!scrubbed.contains("gho_"));
    }

    #[test]
    fn scrub_removes_slack_xoxb_tokens() {
        let input = "SLACK_TOKEN=xoxb-1234-5678-abcdef";
        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
        assert!(scrubbed.contains("[REDACTED]"));
        assert!(!scrubbed.contains("xoxb-"));
    }

    #[test]
    fn scrub_removes_slack_xoxp_tokens() {
        let input = "token xoxp-9999-8888-7777-aabbcc";
        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
        assert!(scrubbed.contains("[REDACTED]"));
        assert!(!scrubbed.contains("xoxp-"));
    }

    #[test]
    fn scrub_removes_long_hex_strings() {
        // 32-char hex string should be caught
        let input = "hash: aabbccdd00112233445566778899aabb";
        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
        assert!(scrubbed.contains("[REDACTED]"));
        assert!(!scrubbed.contains("aabbccdd00112233"));
    }

    #[test]
    fn scrub_multiple_sensitive_items_in_one_string() {
        let input = "Error at /Users/dev/app with token ghp_abcdefghijklmnopqrstuvwxyz1234567890 and key sk-12345678901234567890";
        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
        assert!(scrubbed.contains("[PATH]"));
        assert!(scrubbed.contains("[REDACTED]"));
        assert!(!scrubbed.contains("/Users/dev"));
        assert!(!scrubbed.contains("ghp_"));
        assert!(!scrubbed.contains("sk-"));
    }

    #[test]
    fn scrub_multiple_env_secrets() {
        let mut env = HashMap::new();
        env.insert("API_KEY".to_string(), "key-aaa".to_string());
        env.insert("SECRET_TOKEN".to_string(), "tok-bbb".to_string());

        let input = "failed with key-aaa and tok-bbb";
        let scrubbed = scrub_for_telemetry(input, &env);
        assert!(!scrubbed.contains("key-aaa"));
        assert!(!scrubbed.contains("tok-bbb"));
    }

    #[test]
    fn scrub_preserves_non_secret_env_vars() {
        let mut env = HashMap::new();
        env.insert("RAILS_ENV".to_string(), "production".to_string());
        env.insert("NODE_ENV".to_string(), "development".to_string());

        let input = "Running in production with development mode";
        let scrubbed = scrub_for_telemetry(input, &env);
        // Non-secret env values should not be masked
        assert_eq!(scrubbed, input);
    }

    #[test]
    fn scrub_exact_max_length_not_truncated() {
        // Input exactly at MAX_ERROR_LENGTH should NOT be truncated
        let input: String = "x".repeat(MAX_ERROR_LENGTH);
        let scrubbed = scrub_for_telemetry(&input, &HashMap::new());
        assert_eq!(scrubbed.len(), MAX_ERROR_LENGTH);
        assert!(!scrubbed.contains("...[truncated]"));
    }

    #[test]
    fn scrub_one_over_max_length_is_truncated() {
        let input: String = "y".repeat(MAX_ERROR_LENGTH + 1);
        let scrubbed = scrub_for_telemetry(&input, &HashMap::new());
        assert!(scrubbed.ends_with("...[truncated]"));
    }

    #[test]
    fn scrub_empty_env_value_not_masked() {
        let mut env = HashMap::new();
        env.insert("API_KEY".to_string(), "".to_string());

        let input = "some output text";
        let scrubbed = scrub_for_telemetry(input, &env);
        assert_eq!(scrubbed, input);
    }

    // ── build_report: additional cases ────────────────────────────────

    #[test]
    fn build_report_with_no_exit_code() {
        let report = build_report("npm", "npm install", None, "timeout", "retry", &HashMap::new());
        assert_eq!(report.exit_code, None);
        assert_eq!(report.step_name, "npm");
    }

    #[test]
    fn build_report_scrubs_command_field() {
        let mut env = HashMap::new();
        env.insert("DATABASE_URL".to_string(), "postgres://secret@host/db".to_string());

        let report = build_report(
            "db",
            "psql postgres://secret@host/db",
            Some(1),
            "connection refused",
            "fix",
            &env,
        );
        assert!(!report.command_scrubbed.contains("postgres://secret@host/db"));
    }

    #[test]
    fn build_report_platform_format() {
        let report = build_report("test", "echo", Some(0), "", "retry", &HashMap::new());
        // Platform should be "os-arch" format
        assert!(report.platform.contains('-'), "Platform should be os-arch: {}", report.platform);
        assert_eq!(
            report.platform,
            format!("{}-{}", std::env::consts::OS, std::env::consts::ARCH)
        );
    }

    #[test]
    fn build_report_version_matches_crate() {
        let report = build_report("test", "echo", Some(0), "", "retry", &HashMap::new());
        assert_eq!(report.bivvy_version, env!("CARGO_PKG_VERSION"));
    }

    // ── prompt_telemetry: additional cases ─────────────────────────────

    #[test]
    fn telemetry_prompt_returns_always() {
        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "always");

        let result = prompt_telemetry(&mut ui, &report, None).unwrap();
        assert_eq!(result, TelemetryConsent::Always);
    }

    #[test]
    fn telemetry_prompt_returns_never() {
        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "never");

        let result = prompt_telemetry(&mut ui, &report, None).unwrap();
        assert_eq!(result, TelemetryConsent::Never);
    }

    #[test]
    fn telemetry_prompt_unknown_response_defaults_to_no_thanks() {
        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "garbage");

        let result = prompt_telemetry(&mut ui, &report, None).unwrap();
        assert_eq!(result, TelemetryConsent::NoThanks);
    }

    #[test]
    fn telemetry_unknown_saved_preference_still_prompts() {
        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "send");

        let result = prompt_telemetry(&mut ui, &report, Some("unknown_pref")).unwrap();
        // Unknown saved preference should fall through and prompt
        assert_eq!(result, TelemetryConsent::Send);
        assert!(!ui.prompts_shown().is_empty());
    }

    #[test]
    fn telemetry_prompt_shows_report_details() {
        let report = build_report(
            "bundler",
            "bundle install",
            Some(127),
            "gem not found",
            "shell → retry",
            &HashMap::new(),
        );
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "no_thanks");

        prompt_telemetry(&mut ui, &report, None).unwrap();

        let messages = ui.messages();
        assert!(messages.iter().any(|m| m.contains("bundler")), "Should show step name");
        assert!(messages.iter().any(|m| m.contains("bundle install")), "Should show command");
        assert!(messages.iter().any(|m| m.contains("127")), "Should show exit code");
        assert!(messages.iter().any(|m| m.contains("gem not found")), "Should show error");
        assert!(
            messages.iter().any(|m| m.contains("shell → retry")),
            "Should show recovery action"
        );
    }

    #[test]
    fn telemetry_prompt_hides_exit_code_when_none() {
        let report = build_report("test", "cmd", None, "err", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "no_thanks");

        prompt_telemetry(&mut ui, &report, None).unwrap();

        let messages = ui.messages();
        assert!(
            !messages.iter().any(|m| m.contains("Exit:")),
            "Should not show exit line when exit_code is None"
        );
    }

    #[test]
    fn telemetry_prompt_hides_error_when_empty() {
        let report = build_report("test", "cmd", Some(1), "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "no_thanks");

        prompt_telemetry(&mut ui, &report, None).unwrap();

        let messages = ui.messages();
        assert!(
            !messages.iter().any(|m| m.contains("Error:")),
            "Should not show error line when error is empty"
        );
    }

    // ── save_report_to: additional cases ──────────────────────────────

    #[test]
    fn save_report_creates_nested_directory() {
        let temp = tempfile::TempDir::new().unwrap();
        let nested = temp.path().join("a").join("b").join("c");
        let report = build_report("test", "echo", Some(0), "", "retry", &HashMap::new());

        let path = save_report_to(&report, &nested).unwrap();
        assert!(path.exists());
        assert!(nested.is_dir());
    }

    #[test]
    fn save_report_filename_contains_step_name() {
        let temp = tempfile::TempDir::new().unwrap();
        let report = build_report("my-step", "echo", Some(0), "", "retry", &HashMap::new());

        let path = save_report_to(&report, temp.path()).unwrap();
        let filename = path.file_name().unwrap().to_str().unwrap();
        assert!(filename.ends_with("-my-step.yml"), "Filename should end with step name: {}", filename);
    }

    #[test]
    fn save_report_yaml_roundtrip() {
        let temp = tempfile::TempDir::new().unwrap();
        let report = build_report(
            "webpack",
            "npx webpack build",
            Some(2),
            "module not found",
            "fix → retry",
            &HashMap::new(),
        );

        let path = save_report_to(&report, temp.path()).unwrap();
        let content = std::fs::read_to_string(&path).unwrap();
        let loaded: FailureReport = serde_yaml::from_str(&content).unwrap();

        assert_eq!(loaded.step_name, report.step_name);
        assert_eq!(loaded.command_scrubbed, report.command_scrubbed);
        assert_eq!(loaded.exit_code, report.exit_code);
        assert_eq!(loaded.error_scrubbed, report.error_scrubbed);
        assert_eq!(loaded.recovery_action, report.recovery_action);
        assert_eq!(loaded.bivvy_version, report.bivvy_version);
        assert_eq!(loaded.platform, report.platform);
    }

    #[test]
    fn save_report_yaml_roundtrip_none_exit_code() {
        let temp = tempfile::TempDir::new().unwrap();
        let report = build_report("sig", "cmd", None, "killed", "retry", &HashMap::new());

        let path = save_report_to(&report, temp.path()).unwrap();
        let content = std::fs::read_to_string(&path).unwrap();
        let loaded: FailureReport = serde_yaml::from_str(&content).unwrap();

        assert_eq!(loaded.exit_code, None);
    }

    // ── reports_dir ───────────────────────────────────────────────────

    #[test]
    fn reports_dir_ends_with_expected_path() {
        let dir = reports_dir();
        assert!(dir.ends_with(".bivvy/failure-reports"));
    }

    // ── FailureReport serde ───────────────────────────────────────────

    #[test]
    fn failure_report_serializes_to_yaml() {
        let report = FailureReport {
            step_name: "test".to_string(),
            command_scrubbed: "echo hello".to_string(),
            exit_code: Some(1),
            error_scrubbed: "fail".to_string(),
            recovery_action: "retry".to_string(),
            bivvy_version: "0.1.0".to_string(),
            platform: "linux-x86_64".to_string(),
        };

        let yaml = serde_yaml::to_string(&report).unwrap();
        assert!(yaml.contains("step_name: test"));
        assert!(yaml.contains("exit_code: 1"));
        assert!(yaml.contains("platform: linux-x86_64"));
    }

    #[test]
    fn failure_report_deserializes_from_yaml() {
        let yaml = r#"
step_name: bundler
command_scrubbed: bundle install
exit_code: null
error_scrubbed: "gem error"
recovery_action: shell
bivvy_version: "1.0.0"
platform: macos-aarch64
"#;
        let report: FailureReport = serde_yaml::from_str(yaml).unwrap();
        assert_eq!(report.step_name, "bundler");
        assert_eq!(report.exit_code, None);
        assert_eq!(report.platform, "macos-aarch64");
    }
}

