    // ── FailureReport serde ───────────────────────────────────────────

    #[test]
    fn failure_report_serializes_to_yaml() {
        let report = FailureReport {
            step_name: "test".to_string(),
            command_scrubbed: "echo hello".to_string(),
            exit_code: Some(1),
            error_scrubbed: "fail".to_string(),
            recovery_action: "retry".to_string(),
            bivvy_version: "0.1.0".to_string(),
            platform: "linux-x86_64".to_string(),
        };

        let yaml = serde_yaml::to_string(&report).unwrap();
        assert!(yaml.contains("step_name: test"));
        assert!(yaml.contains("exit_code: 1"));
        assert!(yaml.contains("platform: linux-x86_64"));
    }

    #[test]
    fn failure_report_deserializes_from_yaml() {
        let yaml = r#"
step_name: bundler
command_scrubbed: bundle install
exit_code: null
error_scrubbed: "gem error"
recovery_action: shell
bivvy_version: "1.0.0"
platform: macos-aarch64
"#;
        let report: FailureReport = serde_yaml::from_str(yaml).unwrap();
        assert_eq!(report.step_name, "bundler");
        assert_eq!(report.exit_code, None);
        assert_eq!(report.platform, "macos-aarch64");
    }
